/**
 * helpers.js — Shared configuration for k6 load tests (Phase 5)
 *
 * Provides: BASE_URL, auth headers, token pool, shared thresholds, data IDs.
 */
import { SharedArray } from 'k6/data';

// ─── Base URL ───────────────────────────────────────────────
export const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8089/api';

// ─── Load token data (pre-generated by LoadTestSeeder) ──────
const rawData = JSON.parse(open('./tokens.json'));

export const STUDENTS = new SharedArray('students', () => rawData.students);
export const ADMIN = rawData.admin;
export const LESSON_IDS = new SharedArray('lessons', () => rawData.lesson_ids);
export const MEETING_IDS = new SharedArray('meetings', () => rawData.meeting_ids);
export const COURSE_IDS = new SharedArray('courses', () => rawData.course_ids);

// ─── Auth helper: get token for this VU ─────────────────────
export function authHeaders(vuIndex) {
  const student = STUDENTS[vuIndex % STUDENTS.length];
  return {
    headers: {
      Authorization: `Bearer ${student.token}`,
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
  };
}

// ─── Standard thresholds (from agent.md §7.3) ───────────────
export const STANDARD_THRESHOLDS = {
  http_req_failed: ['rate<0.01'],           // < 1% errors
  http_req_duration: ['p(95)<800', 'p(99)<2000'],  // p95 < 800ms, p99 < 2s
  checks: ['rate>0.99'],                    // > 99% checks pass
};
